fn is_ascii_digit(c: char) -> bool {
    // Check if the character is within the ASCII range '0' to '9'
    ('0'..='9').contains(&c)
}

fn all_digits(s: String) -> bool {
    // For an empty string, return true (vacuously true)
    // For non-empty strings, check that every character is an ASCII digit
    s.chars().all(is_ascii_digit)
}